1: import axios from "axios";
2: import _ from "lodash";
3: import { getAuthUserTokens } from "@topcoder/mfe-header";
4: 
5: export const axiosInstance = axios.create({
6:   headers: {
7:     "Content-Type": "application/json",
8:   },
9: });
10: 
11: // request interceptor to pass auth token
12: axiosInstance.interceptors.request.use((config) => {
13:   return getAuthUserTokens()
14:     .then(({ tokenV3: token }) => {
15:       config.headers["Authorization"] = `Bearer ${token}`;
16:       return config;
17:     })
18:     .catch(() => config);
19: });
20: 
21: // response interceptor to handle error
22: axiosInstance.interceptors.response.use(
23:   (config) => {
24:     // return the response
25:     return config;
26:   },
27:   (error) => {
28:     const serverErrorMessage = _.get(error, "response.data.message");
29: 
30:     // if there is server error message, then return it inside `message` property of error
31:     if (serverErrorMessage) {
32:       error.message = serverErrorMessage;
33:     }
34: 
35:     return Promise.reject(error);
36:   }
37: );

1: /** Get Started page */
2: import React, { useState, useEffect } from "react";
3: import "./styles.module.scss";
4: import { Link, useNavigate } from "@reach/router";
5: import { useSelector } from "react-redux";
6: import withAuthentication from "hoc/withAuthentication";
7: import { setUserProfilePhoto, getAuthUserProfile } from "@topcoder/mfe-header";
8: 
9: // import components and other stuffs
10: import Page from "components/Page";
11: import PageContent from "components/PageContent";
12: import PageDivider from "components/PageDivider";
13: import PageH1 from "components/PageElements/PageH1";
14: import PageH2 from "components/PageElements/PageH2";
15: import PageH3 from "components/PageElements/PageH3";
16: import PageP from "components/PageElements/PageP";
17: import PageUl from "components/PageElements/PageUl";
18: import PageRow from "components/PageElements/PageRow";
19: import PageFoot from "components/PageElements/PageFoot";
20: import PageCard from "components/PageElements/PageCard";
21: import InterestsList from "components/InterestsList";
22: import SkillsList from "components/SkillsList";
23: import Button from "components/Button";
24: import OnboardProgress from "components/OnboardProgress";
25: import UploadPhotoModal from "components/UploadPhotoModal";
26: import AddSkillsModal from "components/AddSkillsModal";
27: import LoadingSpinner from "components/LoadingSpinner";
28: 
29: import {
30:   BUTTON_SIZE,
31:   skills as allSkills,
32:   interests as allInterests,
33: } from "constants";
34: 
35: import IconEdit from "../../assets/images/icon-edit.svg";
36: import IconUpload from "../../assets/images/icon-upload.svg";
37: import IconArrowRight from "../../assets/images/icon-arrow-right.svg";
38: import ImgTestimonial1 from "../../assets/images/testimonial-1.png";
39: import config from "../../../config";
40: 
41: import { getAllSkills, getMemberSkills, updateMySkills } from "services/skills";
42: import {
43:   getMyBasicInfo,
44:   addMyPrimaryInterests,
45:   updateMyPrimaryInterests,
46: } from "services/basicInfo";
47: import { uploadProfilePhoto } from "services/memberData";
48: import _ from "lodash";
49: import {
50:   getTraits,
51:   scrollToTop,
52:   isGetStartedFormDataEmpty,
53:   isNullOrEmpty,
54: } from "utils/";
55: import { getAllCountries } from "services/countries";
56: import { checkUserTrait } from "services/traits";
57: import { trackEvent } from "services/analytics";
58: import { EVENT_TYPE, BUTTON_TYPE } from "constants/";
59: 
60: const GetStarted = () => {
61:   // states
62:   const authUser = useSelector((state) => state.authUser);
63:   const [isLoading, setIsLoading] = useState(false);
64:   const [allSkillsLive, setAllSkillsLive] = useState([]);
65:   const [myProfileData, setMyProfileData] = useState({});
66:   const [myInterests, setMyInterests] = useState([]);
67:   const [selectedSkills, setSelectedSkills] = useState([]);
68:   const [initialMySkills, setInitialMySkills] = useState([]);
69:   const [skillsModalShow, setSkillsModalShow] = useState(false);
70:   const [uploadPhotoModalShow, setUploadPhotoModalShow] = useState(false);
71:   const [profilePhotoSrc, setProfilePhotoSrc] = useState("");
72:   const [profilePhotoSrcBeforeSave, setProfilePhotoSrcBeforeSave] = useState(
73:     ""
74:   );
75:   const [profilePhotoFile, setProfilePhotoFile] = useState(null);
76:   const [skillsModalInitialCategory, setSkillsModalInitialCategory] = useState(
77:     null
78:   );
79:   // track page load
80:   const [loadedDatas, setLoadedDatas] = useState({
81:     memberData: false,
82:     basicInfo: false,
83:     allSkills: false,
84:     mySkills: false,
85:   });
86:   const redirectUrl = config.TOPCODER_COMMUNITY_WEBSITE_URL + "/home";
87: 
88:   // at start, set loading to true
89:   useEffect(() => {
90:     setIsLoading(true);
91: 
92:     scrollToTop();
93:   }, []);
94: 
95:   // count loaded datas, if it's equal to all datas, set loading to false
96:   useEffect(() => {
97:     const loadedCount = Object.values(loadedDatas).reduce(
98:       (a, c) => (c ? a + 1 : a),
99:       0
100:     );
101:     if (loadedCount === Object.values(loadedDatas).length) {
102:       setIsLoading(false);
103:     }
104:   }, [loadedDatas]);
105: 
106:   const handleInterestSelect = (selectedInterest) => {
107:     // if exists, delete it. otherwise, add it
108:     if (
109:       myInterests.find(
110:         (myInterest) => myInterest.name === selectedInterest.name
111:       )
112:     )
113:       setMyInterests(
114:         myInterests.filter(
115:           (myInterest) => myInterest.name !== selectedInterest.name
116:         )
117:       );
118:     else setMyInterests([...myInterests, selectedInterest]);
119:   };
120:   const handleSelectedSkillRemove = (skill) => {
121:     setSelectedSkills(selectedSkills.filter((s) => s.id !== skill.id));
122:   };
123: 
124:   // when profilePhotoSrc changes, tell the navbar to update it
125:   useEffect(() => {
126:     if (!profilePhotoSrc) return;
127:     setUserProfilePhoto(profilePhotoSrc);
128:   }, [profilePhotoSrc]);
129: 
130:   // Get all live skills
131:   useEffect(() => {
132:     setLoadedDatas({ ...loadedDatas, allSkills: false });
133:     getAllSkills()
134:       .then((result) => {
135:         setLoadedDatas((loadedDatas) => ({ ...loadedDatas, allSkills: true }));
136:         setAllSkillsLive(result?.data);
137:         setIsLoading(false);
138:       })
139:       .catch((e) => {
140:         setIsLoading(false);
141:         // eslint-disable-next-line no-console
142:         console.log(e);
143:       });
144:   }, []);
145: 
146:   // Get Member data from redux (firstName, lastName, handle, photoURL) and store it on myProfileData
147:   useEffect(() => {
148:     if (!authUser || !authUser.handle) return;
149:     setLoadedDatas({ ...loadedDatas, memberData: false });
150:     getAuthUserProfile()
151:       .then((result) => {
152:         setLoadedDatas((loadedDatas) => ({ ...loadedDatas, memberData: true }));
153:         setMyProfileData(result);
154:       })
155:       .catch((e) => {
156:         setIsLoading(false);
157:         // eslint-disable-next-line no-console
158:         console.log(e);
159:       });
160:   }, [authUser]);
161: 
162:   // Get skills from server and map them to my selected skills
163:   useEffect(() => {
164:     if (!authUser || !authUser.handle || !allSkillsLive.length) return;
165:     setLoadedDatas({ ...loadedDatas, mySkills: false });
166:     // Get skills from server
167:     getMemberSkills(authUser.handle)
168:       .then((result) => {
169:         // set loadedDatas to track page load
170:         setLoadedDatas((loadedDatas) => ({ ...loadedDatas, mySkills: true }));
171:         let myskills = result?.data?.skills;
172:         if (myskills) myskills = Object.values(myskills);
173:         // map and store on state
174:         const finalMySkills = myskills
175:           .map((myskill) =>
176:             allSkillsLive.find((s) => s.name === myskill.tagName)
177:           )
178:           .filter((s) => s);
179: 
180:         setSelectedSkills(finalMySkills);
181:         setInitialMySkills(finalMySkills);
182:       })
183:       .catch((e) => {
184:         setIsLoading(false);
185:         // toastr.error('Error', 'failed to get profile skills!');
186:       });
187:   }, [authUser, allSkillsLive]);
188: 
189:   // Get Basic Info to get users interests, and map them to my interests
