1: /**
2:  * Authentication
3:  *
4:  * wrap component for authentication
5:  *
6:  * - checks if user is logged-in, and if not, then redirects to the login page
7:  *
8:  * Also, this component load important data for `hasPermission` method:
9:  * - decodes user token and set in Redux Store `authUser.userId, handle, roles`
10:  *   - we need to know user `roles` to check if user user has Topcoder Roles
11:  */
12: import React, { useEffect } from "react";
13: import _ from "lodash";
14: import { getAuthUserTokens, login } from "@topcoder/mfe-header";
15: import LoadingIndicator from "../../components/LoadingIndicator";
16: import { authUserSuccess, authUserError } from "./actions";
17: import { decodeToken } from "tc-auth-lib";
18: import { useDispatch, useSelector } from "react-redux";
19: import {
20:   getOnboardingChecklist,
21:   updateOnboardingWizardTraits,
22: } from "services/onboardingChecklist";
23: 
24: export default function withAuthentication(Component) {
25:   const AuthenticatedComponent = (props) => {
26:     const dispatch = useDispatch();
27:     const { isLoggedIn, authError } = useSelector((state) => state.authUser);
28: 
29:     const updateOnboardingWizardStatus = (handle) => {
30:       getOnboardingChecklist(handle).then(async (checklist) => {
31:         const traits =
32:           checklist.data.length > 0 ? checklist.data[0].traits.data : [];
33: 
34:         const shouldCreate = checklist.data.length === 0;
35:         const onboardingWizardChecklistIndex = traits.findIndex(
36:           (x) => x[`onboarding_wizard`] != null
37:         );
38: 
39:         if (onboardingWizardChecklistIndex === -1) {
40:           traits.push({
41:             onboarding_wizard: {
42:               status: "seen",
43:             },
44:           });
45:           updateOnboardingWizardTraits(handle, traits, shouldCreate);
46:         } else if (
47:           traits[onboardingWizardChecklistIndex].onboarding_wizard?.status ===
48:           "pending_at_user"
49:         ) {
50:           traits[onboardingWizardChecklistIndex].onboarding_wizard.status =
51:             "seen";
52:           updateOnboardingWizardTraits(handle, traits, shouldCreate);
53:         }
54:       });
55:     };
56: 
57:     /*
58:       Check if user is logged-in or redirect ot the login page
59:     */
60:     useEffect(() => {
61:       // prevent page redirecting to login page when unmount
62:       let isUnmount = false;
63:       if (!isLoggedIn) {
64:         getAuthUserTokens()
65:           .then(({ tokenV3 }) => {
66:             if (!!tokenV3) {
67:               const tokenData = decodeToken(tokenV3);
68:               const handle = tokenData.handle;
69: 
70:               updateOnboardingWizardStatus(handle);
71: 
72:               dispatch(
73:                 authUserSuccess(
74:                   _.pick(tokenData, ["userId", "handle", "roles"])
75:                 )
76:               );
77:             } else if (!isUnmount) {
78:               login();
79:             }
80:           })
81:           .catch((error) => dispatch(authUserError(error)));
82:       }
83: 
84:       return () => {
85:         isUnmount = true;
86:       };
87:     }, [dispatch, isLoggedIn]);
88: 
89:     return (
90:       <>
91:         {/* Show loading indicator until we know if user is logged-in or no.
92:             In we got error during this process, show error */}
93:         {isLoggedIn === null && <LoadingIndicator error={authError} />}
94: 
95:         {/* Show component only if user is logged-in */}
96:         {isLoggedIn === true ? <Component {...props} /> : null}
97:       </>
98:     );
99:   };
100: 
101:   return AuthenticatedComponent;
102: }

1: /* global process */
2: /**
3:  * Configure Redux Store
4:  */
5: import { createStore, applyMiddleware } from "redux";
6: import { createLogger } from "redux-logger";
7: import thunk from "redux-thunk";
8: import { createPromise } from "redux-promise-middleware";
9: import rootReducer from "./reducers";
10: 
11: const middlewares = [
12:   // if payload of action is promise it would split action into 3 states
13:   createPromise({
14:     promiseTypeSuffixes: ["PENDING", "SUCCESS", "ERROR"],
15:   }),
16:   thunk,
17: ];
18: 
19: // enable Redux Logger in in DEV environment
20: if (process.env.NODE_ENV === "development") {
21:   const { createLogger } = require("redux-logger");
22:   const logger = createLogger();
23:   middlewares.push(logger);
24: }
25: 
26: const store = createStore(rootReducer, applyMiddleware(...middlewares));
27: 
28: export default store;
